import React, { useState } from 'react';

function ProfileModal({ onComplete, onClose }) {
  const [realName, setRealName] = useState('');
  const [age, setAge] = useState('');
  const [allergyHistory, setAllergyHistory] = useState('');
  const [chronicDiseases, setChronicDiseases] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = () => {
    if (!realName) {
      alert('请输入您的姓名');
      return;
    }

    setIsSubmitting(true);
    setTimeout(() => {
      onComplete({
        realName,
        age: age ? parseInt(age) : null,
        allergyHistory: allergyHistory || null,
        chronicDiseases: chronicDiseases || null
      });
      setIsSubmitting(false);
    }, 1000);
  };

  const handleSkip = () => {
    onComplete({
      realName: '用户',
      age: null,
      allergyHistory: null,
      chronicDiseases: null
    });
  };

  return (
    <div style={{
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      background: 'rgba(0,0,0,0.6)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      zIndex: 1000
    }}>
      <div style={{
        background: 'white',
        padding: '40px 50px',
        borderRadius: '20px',
        boxShadow: '0 20px 60px rgba(0,0,0,0.3)',
        width: '100%',
        maxWidth: '500px',
        maxHeight: '90vh',
        overflowY: 'auto'
      }}>
        <div style={{ textAlign: 'center', marginBottom: '30px' }}>
          <div style={{ fontSize: '56px', marginBottom: '15px' }}>👤</div>
          <h2 style={{ fontSize: '28px', fontWeight: 'bold', color: '#667eea' }}>完善个人档案</h2>
          <p style={{ fontSize: '18px', color: '#666', marginTop: '8px' }}>为了给您提供更准确的用药建议</p>
        </div>

        <div style={{ marginBottom: '24px' }}>
          <label style={{ 
            fontSize: '20px', 
            fontWeight: '600', 
            marginBottom: '10px', 
            display: 'block',
            color: '#444'
          }}>
            <span style={{ color: '#e74c3c' }}>*</span> 您的称呼
          </label>
          <input
            type="text"
            value={realName}
            onChange={(e) => setRealName(e.target.value)}
            placeholder="请输入您的姓名或称呼"
            style={{
              width: '100%',
              padding: '16px 20px',
              fontSize: '20px',
              border: '3px solid #ddd',
              borderRadius: '12px',
              outline: 'none',
              transition: 'all 0.3s ease'
            }}
            onFocus={(e) => e.target.style.borderColor = '#667eea'}
            onBlur={(e) => e.target.style.borderColor = '#ddd'}
          />
        </div>

        <div style={{ marginBottom: '24px' }}>
          <label style={{ 
            fontSize: '20px', 
            fontWeight: '600', 
            marginBottom: '10px', 
            display: 'block',
            color: '#444'
          }}>年龄（选填）</label>
          <input
            type="number"
            value={age}
            onChange={(e) => setAge(e.target.value)}
            placeholder="请输入您的年龄"
            min="0"
            max="120"
            style={{
              width: '100%',
              padding: '16px 20px',
              fontSize: '20px',
              border: '3px solid #ddd',
              borderRadius: '12px',
              outline: 'none',
              transition: 'all 0.3s ease'
            }}
            onFocus={(e) => e.target.style.borderColor = '#667eea'}
            onBlur={(e) => e.target.style.borderColor = '#ddd'}
          />
        </div>

        <div style={{ marginBottom: '24px' }}>
          <label style={{ 
            fontSize: '20px', 
            fontWeight: '600', 
            marginBottom: '10px', 
            display: 'block',
            color: '#444'
          }}>过敏史（选填）</label>
          <textarea
            value={allergyHistory}
            onChange={(e) => setAllergyHistory(e.target.value)}
            placeholder="例如：青霉素过敏、海鲜过敏"
            rows="3"
            style={{
              width: '100%',
              padding: '16px 20px',
              fontSize: '20px',
              border: '3px solid #ddd',
              borderRadius: '12px',
              outline: 'none',
              resize: 'none',
              transition: 'all 0.3s ease'
            }}
            onFocus={(e) => e.target.style.borderColor = '#667eea'}
            onBlur={(e) => e.target.style.borderColor = '#ddd'}
          />
        </div>

        <div style={{ marginBottom: '30px' }}>
          <label style={{ 
            fontSize: '20px', 
            fontWeight: '600', 
            marginBottom: '10px', 
            display: 'block',
            color: '#444'
          }}>慢性病史（选填）</label>
          <textarea
            value={chronicDiseases}
            onChange={(e) => setChronicDiseases(e.target.value)}
            placeholder="例如：高血压、糖尿病、冠心病"
            rows="3"
            style={{
              width: '100%',
              padding: '16px 20px',
              fontSize: '20px',
              border: '3px solid #ddd',
              borderRadius: '12px',
              outline: 'none',
              resize: 'none',
              transition: 'all 0.3s ease'
            }}
            onFocus={(e) => e.target.style.borderColor = '#667eea'}
            onBlur={(e) => e.target.style.borderColor = '#ddd'}
          />
        </div>

        <div style={{ display: 'flex', gap: '16px' }}>
          <button
            onClick={handleSkip}
            style={{
              flex: 1,
              padding: '18px',
              fontSize: '20px',
              fontWeight: '600',
              background: '#f5f5f5',
              color: '#666',
              border: 'none',
              borderRadius: '12px',
              cursor: 'pointer',
              transition: 'all 0.3s ease'
            }}
          >
            跳过
          </button>
          <button
            onClick={handleSubmit}
            disabled={isSubmitting}
            style={{
              flex: 2,
              padding: '18px',
              fontSize: '20px',
              fontWeight: '600',
              background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
              color: 'white',
              border: 'none',
              borderRadius: '12px',
              cursor: isSubmitting ? 'not-allowed' : 'pointer',
              boxShadow: '0 6px 16px rgba(102, 126, 234, 0.3)',
              transition: 'all 0.3s ease'
            }}
          >
            {isSubmitting ? '保存中...' : '保存并继续'}
          </button>
        </div>
      </div>
    </div>
  );
}

export default ProfileModal;
